WITH unpacked AS (SELECT id, service, host, latency_ms, status_code, payload_json, context, COALESCE(context['trace'], 'direct') AS trace_or_default, COALESCE(context['region'], 'unknown') AS region_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE latency_ms <= 1193) SELECT id, service, host, latency_ms, status_code, payload_json, context, trace_or_default, region_or_default, duration_text, status_code_high, NTILE(5) OVER (PARTITION BY service ORDER BY status_code DESC, id) AS status_code_bucket, LAST_VALUE(status_code_high, TRUE) OVER (ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_status_code_high, SUM(status_code) OVER (PARTITION BY service ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_code, CORR(status_code, latency_ms) OVER (PARTITION BY host, service) AS corr_status_code_latency_ms FROM unpacked;
